use gielinor_client::{disk_cache::DiskCache,actor_overlay::{Hitsplat,HealthBar},Result};use std::io::Write;
fn main()->Result<()> {let args:Vec<_>=std::env::args().collect();let mut cache=DiskCache::open(&args[1],64<<20)?;let mut output=std::fs::File::create(&args[2])?;let mut out=vec![];for group in [32,33] {let all=cache.group(2,group,[0;4])?;out.extend_from_slice(&(all.len() as u32).to_be_bytes());for (id,data) in all {if group==32 {Hitsplat::decode(id,&data)?;}else{HealthBar::decode(id,&data)?;}out.extend_from_slice(&id.to_be_bytes());out.extend_from_slice(&(data.len() as u32).to_be_bytes());out.extend_from_slice(&data);}}output.write_all(&out)?;println!("Exported original cache hit-splat and health-bar definitions");Ok(())}
